package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import org.jlinalg.gprofiler.GprofilerJson;
import static org.jlinalg.cli.GprofilerWorkflowContracts.*;
import static org.jlinalg.cli.ScenicWorkflowFiles.*;
import static org.jlinalg.cli.PrsiceContracts.ACTION;
import static org.jlinalg.cli.PrsiceContracts.COMPLETE;
import static org.jlinalg.cli.PrsiceContracts.PROFILE;

/** Original PRSice C&T, scoring and association with native audits and private captures. */
public final class PrsiceToolsCli {
    private PrsiceToolsCli() { }
    public static void main(String[] args){int code=run(args,System.out,System.err);if(code!=0)System.exit(code);}
    static int run(String[] args,PrintStream out,PrintStream err){
        Path root=null;
        try {
            if(Arrays.equals(args,new String[]{"--help"})){out.println(help());return 0;}
            if(args.length==2&&args[0].equals("--export-setup")){Path directory=newOutput(Path.of(args[1]));for(String name:List.of("SOURCE.json","LICENSE-upstream.txt","setup.py"))Files.write(directory.resolve(name),PrsiceRuntime.resource(name),StandardOpenOption.CREATE_NEW);out.println("Exported pinned PRSice setup helper; no download, installation or analysis executed. Run python setup.py --help. "+ACTION);return 0;}
            if(args.length==2&&args[0].equals("--inspect")){inspect(Path.of(args[1]));out.println("SAVED_PRSICE_CAPTURE_CHECKED: captured scores reconstructed; original regressions not refitted. "+ACTION);return 0;}
            require(args.length==2&&args[0].equals("--request"),"Use --request JSON, --inspect CAPTURE or --help");Path file=Path.of(args[1]).toAbsolutePath().normalize();byte[] raw=bytes(file,16777216);var source=object(GprofilerJson.read(raw));String mode=text(source.get("mode"),"mode");Path parent=null;Map<String,Object> parentSeal=null;var request=new LinkedHashMap<String,Object>();
            if(Set.of("VERIFY","REPLAY").contains(mode)){
                keys(source,Set.of("schema_version","mode","analysis","out","runtime_home"));integer(source.get("schema_version"),1,1);parent=resolve(file.getParent(),text(source.get("analysis"),"analysis"));request.putAll(inspect(parent));parentSeal=pin(parent.resolve("manifest.json"));request.put("bundle",parent.resolve("inputs").toString());request.put("out",resolve(file.getParent(),text(source.get("out"),"out")).toString());request.put("runtime_home",source.containsKey("runtime_home")?resolve(file.getParent(),text(source.get("runtime_home"),"runtime_home")).toString():read(parent.resolve("runtime-binding.json")).get("runtime_home"));
            }else request.putAll(PrsiceContracts.validate(source));
            var validated=PrsiceContracts.validate(request);Path target=resolve(file.getParent(),text(validated.get("out"),"out")),home=resolve(file.getParent(),text(validated.get("runtime_home"),"runtime_home")),bundle=resolve(file.getParent(),text(validated.get("bundle"),"bundle"));
            require(!target.startsWith(home)&&!home.startsWith(target)&&!bundle.startsWith(target),"NEW output must be disjoint from runtime and cannot contain the input bundle");if(parent!=null)require(!target.startsWith(parent)&&!parent.startsWith(target),"Fresh output and parent evidence must be disjoint");
            // Verify every declared source path before creating owned output.
            if(!Files.isDirectory(bundle))throw new PrsiceContracts.Unavailable("Missing permitted input bundle: "+bundle);require(bundle.toRealPath().equals(bundle),"Use a physical input bundle without aliases");var resolved=new LinkedHashMap<String,Path>();
            for(var entry:object(validated.get("inputs")).entrySet()){Path path=bundle.resolve(relative(text(entry.getValue(),entry.getKey()))).normalize();if(!Files.exists(path))throw new PrsiceContracts.Unavailable("Missing exact permitted "+entry.getKey()+" input "+path);require(path.startsWith(bundle)&&path.toRealPath().equals(path)&&Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)&&!path.startsWith(target),"Use regular physical bundle members outside NEW output");resolved.put(entry.getKey(),path);}
            root=newOutput(target);Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("worker"));Files.write(root.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);var canonical=PrsiceContracts.canonical(validated);write(root.resolve("canonical-request.json"),canonical);write(root.resolve("source-origin.json"),map("execution_mode",mode,"source_request_address",file.toString(),"creation_address",root.toString()));
            ScenicWorkflowFiles.text(root.resolve("WARNINGS.md"),"# PRSICE: REVIEW BEFORE USING RESULTS\n\n"+ACTION+"\n\nOnly a capture with valid COMPLETED.json and results_admitted=true is admitted. Clumping and regressions execute the pinned original binary. Native Java reconstructs exported hard-call scores; saved inspection does not refit regression or independently certify LD clumps, convergence or biological validity. Scores and fits retain original export precision (9 and 6 significant digits). Reference and target ancestry/build labels are user declarations, not inferred population verification. No held-out accuracy or cross-validation is inferred.\n");
            write(root.resolve("RUNNING.json"),map("status","RUNNING_NO_RESULT_ADMITTED","mode",mode));write(root.resolve("producer.json"),producer());sources(root,false);write(root.resolve("runtime-binding.json"),map("runtime_home",home.toString()));
            if(parent!=null)for(var pair:Map.of("canonical-request.json","parent-canonical-request.json","manifest.json","parent-manifest.json","COMPLETED.json","parent-COMPLETED.json","producer.json","parent-producer.json").entrySet())Files.copy(parent.resolve(pair.getKey()),root.resolve(pair.getValue()));
            var captures=map();var bindings=map();for(var entry:resolved.entrySet()){String name="inputs/"+PrsiceContracts.INPUT_FILES.get(entry.getKey());capture(entry.getValue(),root.resolve(name),canonical,captures,name);bindings.put(entry.getKey(),map("declared",object(validated.get("inputs")).get(entry.getKey()),"resolved",entry.getValue().toString(),"captured",name,"identity",captures.get(name)));}write(root.resolve("input-inventory.json"),captures);write(root.resolve("input-binding.json"),bindings);var attributes=attributes(root,captures);
            Map<String,Object> audit;
            try(var inputs=PrsiceData.read(root,canonical)){
                write(root.resolve("input-audit.json"),inputs.summary);write(root.resolve("prepared-input.json"),PrsiceData.prepared(root,canonical,inputs,true));
                Path executable=PrsiceRuntime.executable(home);var runtime=runtime(executable);write(root.resolve("runtime-before.json"),runtime);var environment=PrsiceRuntime.environment(root,canonical);Path captured=root;var version=map();
                try {require(PrsiceProcess.execute(List.of(executable.toString(),"--version"),environment,root,canonical,version,()->unchanged(captured,attributes),"version")==0,"Original version check failed");}
                finally {write(root.resolve("version-process.json"),version);}
                String report=Files.readString(root.resolve("worker/version.stdout.log"),StandardCharsets.UTF_8)+Files.readString(root.resolve("worker/version.stderr.log"),StandardCharsets.UTF_8);require(report.contains("2.3.5 (2021-09-20)"),"Original executable reports unexpected version/date");var process=map();
                try {require(PrsiceProcess.execute(PrsiceRuntime.command(root,executable,canonical),environment,root,canonical,process,()->unchanged(captured,attributes),"analysis")==0,"Original PRSice exited unsuccessfully; partial products remain unadmitted");}
                finally {write(root.resolve("analysis-process.json"),process);}
                write(root.resolve("runtime-after.json"),runtime(PrsiceRuntime.executable(home)));require(same(runtime,read(root.resolve("runtime-after.json"))),"Original runtime changed during analysis");for(var entry:captures.entrySet())require(same(entry.getValue(),pin(root.resolve(entry.getKey()))),"Captured input changed during original analysis");
                audit=PrsiceAudit.evaluate(root,canonical,inputs,false);write(root.resolve("scientific-audit.json"),audit);Files.writeString(root.resolve("WARNINGS.md"),"\n## Observed review items\n\n"+String.join("\n\n",list(audit.get("warnings")).stream().map(Object::toString).toList())+"\n",StandardCharsets.UTF_8,StandardOpenOption.APPEND);
            }
            PrsiceProcess.footprint(root,canonical);if(parent!=null){inspect(parent);require(same(parentSeal,pin(parent.resolve("manifest.json"))),"Parent capture changed during fresh computation");var matched=map();for(String name:compared(root)){var identity=pin(root.resolve(name));require(same(identity,pin(parent.resolve(name))),"Fresh "+mode+" scientific/runtime bytes differ: "+name);matched.put(name,identity);}require(compared(root).equals(compared(parent)),"Fresh scientific product namespace differs");write(root.resolve("fresh-comparison.json"),map("mode",mode,"new_original_computation_executed",true,"parent_manifest",parentSeal,"matched_files",matched,"paths_logs_timings_compared",false));}
            write(root.resolve("analysis-status.json"),map("status",COMPLETE,"results_admitted",true,"profile",PROFILE,"required_action",ACTION));var manifest=map("schema_version",1,"profile",PROFILE,"status",COMPLETE,"mode",mode,"scientific_summary",audit,"private_capture",true,"new_family_credit",0,"new_reviews",0,"whole_goal_complete",false,"inventory",inventory(root,canonical));write(root.resolve("manifest.json"),manifest);write(root.resolve("COMPLETED.json"),map("status",COMPLETE,"manifest",pin(root.resolve("manifest.json"))));inspect(root);out.println(COMPLETE+" "+root);err.println("PRSICE REVIEW: "+list(audit.get("warnings")).size()+" review items. "+ACTION);return 0;
        }catch(Exception|OutOfMemoryError error){
            int code=error instanceof PrsiceContracts.Unavailable||error instanceof ScenicWorkflowContracts.Unavailable||error instanceof NoSuchFileException?3:2;String state=code==3?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT";
            if(root!=null)try{for(String name:List.of("COMPLETED.json","analysis-status.json"))if(Files.exists(root.resolve(name),LinkOption.NOFOLLOW_LINKS))Files.move(root.resolve(name),root.resolve("UNADMITTED-"+name));write(root.resolve("analysis-status.json"),map("status",state,"results_admitted",false,"cause",error.toString(),"required_action",ACTION));ScenicWorkflowFiles.text(root.resolve("FAILURE.md"),"# "+state+"\n\n"+error+"\n\n"+ACTION+"\n");}catch(Exception second){error.addSuppressed(second);}err.println(state+": "+error+"\n"+ACTION);return code;
        }
    }
    private static Map<String,Object> runtime(Path executable)throws IOException {return map("platform",PrsiceRuntime.platform(),"executable",pin(executable),"profile",PROFILE,"version","2.3.5 (2021-09-20)");}
    static Map<String,Object> producer()throws IOException {try{Path path=Path.of(PrsiceToolsCli.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath();if(!Files.isRegularFile(path)||!path.getFileName().toString().endsWith(".jar"))throw new PrsiceContracts.Unavailable("Build/use the complete executable JAR; original workflow execution and inspection require its exact retained producer, not loose classes");return map("complete_executable_JAR",pin(path),"source_descriptor",pin(PrsiceRuntime.resource("SOURCE.json")));}catch(java.net.URISyntaxException e){throw new IOException("Cannot identify producer JAR",e);}}
    private static void sources(Path root,boolean inspect)throws IOException {for(String name:List.of("SOURCE.json","LICENSE-upstream.txt")){byte[] bytes=PrsiceRuntime.resource(name);if(inspect)require(Arrays.equals(bytes,ScenicWorkflowFiles.bytes(root.resolve(name),16777216)),"Captured source/profile resource changed");else Files.write(root.resolve(name),bytes,StandardOpenOption.CREATE_NEW);}}
    private static Map<String,BasicFileAttributes> attributes(Path root,Map<String,Object> captures)throws IOException {var result=new TreeMap<String,BasicFileAttributes>();for(String name:captures.keySet())result.put(name,Files.readAttributes(root.resolve(name),BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS));return result;}
    private static void unchanged(Path root,Map<String,BasicFileAttributes> expected)throws IOException {for(var e:expected.entrySet()){var now=Files.readAttributes(root.resolve(e.getKey()),BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);var before=e.getValue();require(now.isRegularFile()&&!now.isSymbolicLink()&&now.size()==before.size()&&now.lastModifiedTime().equals(before.lastModifiedTime())&&Objects.equals(now.fileKey(),before.fileKey()),"Captured input attributes changed during original execution");}}
    private static SortedSet<String> compared(Path root)throws IOException {var result=new TreeSet<>(Set.of("input-audit.json","prepared-input.json","scientific-audit.json","sample-ledger.tsv","variant-ledger.tsv","runtime-before.json"));if(Files.exists(root.resolve("results.tsv")))result.add("results.tsv");try(var stream=Files.list(root.resolve("worker"))){for(Path path:stream.toList()){String name=path.getFileName().toString();if(name.startsWith("original.")&&!name.endsWith(".log"))result.add("worker/"+name);}}return result;}
    private static Map<String,Object> validateSaved(Map<String,Object> request)throws IOException {var restored=new LinkedHashMap<>(request);restored.put("runtime_home","captured-runtime");restored.put("bundle","captured-inputs");restored.put("out","unused-new-output");return PrsiceContracts.canonical(PrsiceContracts.validate(restored));}
    static Map<String,Object> inspect(Path address)throws IOException {
        try{return inspectCapture(address);}catch(ScenicWorkflowContracts.Unavailable|NoSuchFileException error){throw new IOException("Incomplete saved PRSice capture; no result admitted. Restore the unchanged complete capture and exact producer; never reseal missing or changed evidence.",error);}
    }
    private static Map<String,Object> inspectCapture(Path address)throws IOException {
        Path root=address.toAbsolutePath().normalize();require(root.toRealPath().equals(root)&&Files.isDirectory(root,LinkOption.NOFOLLOW_LINKS),"Use a physical saved capture");require(!Files.exists(root.resolve("FAILURE.md")),"Failed/skipped capture is unadmitted");var seal=read(root.resolve("COMPLETED.json"));var manifest=read(root.resolve("manifest.json"));require(COMPLETE.equals(seal.get("status"))&&COMPLETE.equals(manifest.get("status"))&&PROFILE.equals(manifest.get("profile"))&&same(seal.get("manifest"),pin(root.resolve("manifest.json"))),"Missing/changed completed PRSice seal");var request=read(root.resolve("canonical-request.json"));require(same(request,validateSaved(request)),"Saved request is not canonical");require(same(producer(),read(root.resolve("producer.json"))),"Restore the exact retained complete producer JAR; never refresh old producer hashes");require(same(manifest.get("inventory"),inventory(root,request)),"Capture bytes or namespace changed");sources(root,true);
        var origin=read(root.resolve("source-origin.json"));var original=read(root.resolve("source-request.json"));String mode=text(origin.get("execution_mode"),"mode");require(mode.equals(manifest.get("mode")),"Changed execution mode");if(mode.equals("RUN"))require(same(request,PrsiceContracts.canonical(PrsiceContracts.validate(original))),"Source/canonical request differs");else{
            require(Set.of("VERIFY","REPLAY").contains(mode)&&mode.equals(original.get("mode")),"Unknown fresh operation");require(same(request,read(root.resolve("parent-canonical-request.json")))&&same(read(root.resolve("producer.json")),read(root.resolve("parent-producer.json")))&&same(read(root.resolve("parent-COMPLETED.json")).get("manifest"),pin(root.resolve("parent-manifest.json"))),"Changed saved parent scientific request/producer/seal");var comparison=read(root.resolve("fresh-comparison.json"));require(mode.equals(comparison.get("mode"))&&Boolean.TRUE.equals(comparison.get("new_original_computation_executed"))&&same(comparison.get("parent_manifest"),pin(root.resolve("parent-manifest.json")))&&compared(root).equals(object(comparison.get("matched_files")).keySet()),"Incomplete fresh comparison population/provenance");for(var e:object(comparison.get("matched_files")).entrySet())require(same(e.getValue(),pin(root.resolve(relative(e.getKey())))),"Changed fresh compared product");
        }
        var captures=read(root.resolve("input-inventory.json"));var bindings=read(root.resolve("input-binding.json"));var expected=new TreeSet<String>();for(String role:object(request.get("inputs")).keySet())expected.add("inputs/"+PrsiceContracts.INPUT_FILES.get(role));require(captures.keySet().equals(expected)&&bindings.keySet().equals(object(request.get("inputs")).keySet()),"Changed captured input role population");for(var e:captures.entrySet())require(same(e.getValue(),pin(root.resolve(relative(e.getKey())))),"Changed captured input");for(var e:bindings.entrySet()){var b=object(e.getValue());String name="inputs/"+PrsiceContracts.INPUT_FILES.get(e.getKey());require(name.equals(b.get("captured"))&&same(b.get("identity"),captures.get(name)),"Changed source/input binding");if(mode.equals("RUN"))require(Objects.equals(b.get("declared"),object(original.get("inputs")).get(e.getKey())),"Changed declared source input path");}
        Map<String,Object> audit;try(var inputs=PrsiceData.read(root,request)){require(same(inputs.summary,read(root.resolve("input-audit.json"))),"Changed input audit");require(same(PrsiceData.prepared(root,request,inputs,false),read(root.resolve("prepared-input.json"))),"Changed deterministic prepared weight input");audit=PrsiceAudit.evaluate(root,request,inputs,true);}require(same(audit,read(root.resolve("scientific-audit.json")))&&same(audit,manifest.get("scientific_summary")),"Changed reconstructed scientific audit");var before=read(root.resolve("runtime-before.json"));require(PROFILE.equals(before.get("profile"))&&same(before,read(root.resolve("runtime-after.json")))&&same(before.get("executable"),object(PrsiceRuntime.profile().get("runtime_executables")).get(text(before.get("platform"),"platform"))),"Changed original runtime identity");var status=read(root.resolve("analysis-status.json"));require(COMPLETE.equals(status.get("status"))&&Boolean.TRUE.equals(status.get("results_admitted")),"Saved result unadmitted");return request;
    }
    static String help(){return """
        prsice-tools --request JSON | --inspect CAPTURE | --export-setup NEWDIR | --help
        Original pinned PRSice 2.3.5, single-Base autosomal diploid SNP-major BED.
        CLUMP: original target/reference haplotype LD clumping.
        SCORE: C&T or prepared-weight scoring; native Java reconstructs scores.
        PREDICT: original single-trait quantitative/binary association, covariates,
        categorical covariates and explicitly requested permutations.
        RUN schema1 requires profile,operation,runtime_home,bundle,inputs,
        parameters,policies,limits,NEW out. All scientific choices are explicit.
        VERIFY/REPLAY schema1: mode,analysis,NEW out,optional runtime_home.
        Both run a fresh original analysis, requiring matching scientific/runtime
        products. --inspect is read only, reconstructs captured scores and does
        not require an installed original runtime or refit original regressions.
        Captures and raw logs are private. Exact complete producer JAR required.
        Exit0 scoped complete;3 unavailable/prohibited dependency, analysis
        skipped;2 failure, no complete result. Existing output is preserved.
        Read docs/PRSICE_WORKFLOW.md for schema, installation and source limits.
        """+ACTION;}
}
